8	// ExtractBearerToken extracts the JWT token from an Authorization header value.
9	// Expected format: "Bearer {token}"
10	// Returns empty string if no valid bearer token is found.
11	func ExtractBearerToken(authHeader string) string {
12		if authHeader == "" {
13			return ""
14		}
15		parts := strings.Fields(authHeader)
16		if len(parts) != 2 || !strings.EqualFold(parts[0], "bearer") {
17			return ""
18		}
19		return parts[1]
20	}
21	
22	// ExtractRefreshTokenFromCookie extracts the refresh token from cookie header.
23	func ExtractRefreshTokenFromCookie(cookieHeader string) string {
24		if cookieHeader == "" {
25			return ""
26		}
27		req := &http.Request{Header: http.Header{"Cookie": []string{cookieHeader}}}
28		cookie, err := req.Cookie(RefreshTokenCookieName)
29		if err != nil {
30			return ""
31		}
32		return cookie.Value
33	}
