246	func (s *APIV1Service) fetchCurrentUser(ctx context.Context) (*store.User, error) {
247		userID := auth.GetUserID(ctx)
248		if userID == 0 {
249			return nil, nil
250		}
251		user, err := s.Store.GetUser(ctx, &store.FindUser{
252			ID: &userID,
